int main(int argc,const char **argv){@autoreleasepool{if(argc<4)return 2;NSString *operation=@(argv[1]),*root=@(argv[2]);NSData *data=[@(argv[3]) isEqual:@"-"]?[NSFileHandle.fileHandleWithStandardInput readDataToEndOfFile]:[@(argv[3]) dataUsingEncoding:NSUTF8StringEncoding];NSDictionary *input=[NSJSONSerialization JSONObjectWithData:data options:0 error:nil]?:@{};TMCGitService *g=[[TMCGitService alloc] initWithRoot:root];g.cancelled=[input[@"cancel"] boolValue];NSError *error=nil;id result=nil;if([operation isEqual:@"upstream"])result=@([g setUpstream:input[@"name"] error:&error]);if([operation isEqual:@"status"])result=[g status:&error];if([operation isEqual:@"init"])result=@([g initialize:&error]);if([operation isEqual:@"stage"])result=@([g stage:input[@"paths"] remove:[input[@"remove"] boolValue] error:&error]);if([operation isEqual:@"commit"])result=[g commit:input[@"message"] name:@"Test" email:@"test@example.com" error:&error];if([operation isEqual:@"settings"]){result=@([TMCGitPreferences saveProject:input root:root error:&error]);if([input[@"push"] boolValue])[TMCGitPreferences confirmPushURL:input[@"pushURL"] branch:input[@"pushBranch"] root:root];}if([operation isEqual:@"autoPush"]){result=[g pushArchive:input[@"id"] foreground:input[@"foreground"]?[input[@"foreground"] boolValue]:YES];[TMCGitPreferences record:result root:root];}if([operation isEqual:@"archive"])result=[g archive:input[@"message"] protection:[input[@"protection"] boolValue] name:input[@"name"]?:@"Test" email:input[@"email"]?:@"test@example.com" error:&error];if([operation isEqual:@"history"])result=[g history:&error];if([operation isEqual:@"branch"])result=@([g branch:input[@"name"] action:input[@"action"] error:&error]);if([operation isEqual:@"merge"])result=@([g mergeBranch:input[@"name"] error:&error]);if([operation isEqual:@"remote"])result=@([g setRemote:input[@"url"] error:&error]);if([operation isEqual:@"clone"])result=@([g cloneURL:input[@"url"] error:&error]);if([operation isEqual:@"network"])result=@([g network:input[@"action"] name:@"Test" email:@"test@example.com" error:&error]);if([operation isEqual:@"conflicts"])result=[g conflicts:&error];if([operation isEqual:@"resolve"])result=@([g resolve:input[@"path"] choice:input[@"choice"] text:input[@"text"] expected:input[@"fingerprint"] error:&error]);if([operation isEqual:@"abort"])result=@([g abortMerge:&error]);if([operation isEqual:@"revisionPreview"])result=[g revisionRestorePreview:input[@"revision"] error:&error];if([operation isEqual:@"checkpoint"])result=[g checkpoint:input[@"reason"] error:&error];if([operation isEqual:@"restorePreview"])result=[g restorePreview:input[@"path"] revision:input[@"revision"] error:&error];if([operation isEqual:@"restore"])result=@([g applyRestore:input error:&error]);if([operation isEqual:@"undo"])result=@([g undoRestore:&error]);if([operation isEqual:@"credential"])result=@([TMCGitService saveCredentialForURL:input[@"url"] username:input[@"username"] token:input[@"token"] error:&error]);NSDictionary *response=@{@"result":result?:NSNull.null,@"error":error.localizedDescription?:@""};NSData *output=[NSJSONSerialization dataWithJSONObject:response options:NSJSONWritingPrettyPrinted error:nil];fwrite(output.bytes,1,output.length,stdout);return error?1:0;}}
